import sys
import math

class InputReader:
    def __init__(self, stream):
        self.stream = stream
        self.buffer = ''
        self.tokens = []

    def next(self):
        while not self.tokens:
            line = self.stream.readline()
            if not line:
                return ''
            line = line.strip()
            if line:
                self.tokens = line.split()
        return self.tokens.pop(0)

    def nextInt(self):
        return int(self.next())

class LuckyTickets:
    MOD = 998244353

    def solve(self, testNumber, in_stream, out_stream):
        N = 0
        k = 0
        try:
            N = in_stream.nextInt()
            k = in_stream.nextInt()
        except:
            pass
        dig = [0] * 11
        for _ in range(k):
            try:
                val = in_stream.nextInt()
                dig[10 - val] = 1
            except:
                pass
        power = N // 2
        res = [1]
        while power > 0:
            if (power & 1) > 0:
                res = self.convoluteSimply(res.copy(), dig.copy(), self.MOD, 3)
            dig = self.convoluteSimply(dig.copy(), dig.copy(), self.MOD, 3)
            power >>= 1
        output = 0
        for val in res:
            output += val * val
            output %= self.MOD
        out_stream.write(str(output) + '\n')

    @staticmethod
    def convoluteSimply(a, b, P, g):
        m = max(2, 1 << (max(a.__len__(), b.__len__()) - 1).bit_length() + 1)
        fa = LuckyTickets.nttmb(a, m, False, P, g)
        if a is b:
            fb = fa
        else:
            fb = LuckyTickets.nttmb(b, m, False, P, g)
        for i in range(m):
            fa[i] = fa[i] * fb[i] % P
        return LuckyTickets.nttmb(fa, m, True, P, g)

    @staticmethod
    def nttmb(src, n, inverse, P, g):
        dst = src[:n] + [0] * (n - len(src))
        h = n.bit_length() - 1
        K = 1 << (h + 1)
        H = (K.bit_length() - 1) * 2
        M = (K * K) // P
        wws = [0] * (1 << (h - 1))
        dw = pow(g, P - 1 - (P - 1) // n, P) if inverse else pow(g, (P - 1) // n, P)
        w = (1 << 32) % P
        for k in range(1 << (h - 1)):
            wws[k] = int(w)
            w = LuckyTickets.modh(w * dw, M, H, P)
        J = LuckyTickets.invl(P, 1 << 32)
        for i in range(h):
            for j in range(1 << i):
                s = j << (h - i)
                t = s | 1 << (h - i - 1)
                for k in range(1 << (h - i - 1)):
                    s_idx = s + k
                    t_idx = t + k
                    u = (dst[s_idx] - dst[t_idx] + 2 * P) * wws[k] % P
                    dst[s_idx] = (dst[s_idx] + dst[t_idx]) % P
                    Q = ((u << 32) * J) >> 32
                    dst[t_idx] = (u >> 32) - (Q * P >> 32) + P
            if i < h - 1:
                for k in range(1 << (h - i - 2)):
                    wws[k] = wws[k * 2]
        for i in range(n):
            if dst[i] >= P:
                dst[i] -= P
        for i in range(n):
            rev = int('{:b}'.format(i).zfill(h)[::-1], 2)
            if i < rev:
                dst[i], dst[rev] = dst[rev], dst[i]
        if inverse:
            in_val = LuckyTickets.invl(n, P)
            for i in range(n):
                dst[i] = LuckyTickets.modh(dst[i] * in_val, (1 << (K.bit_length() - 1)) * 2 // P, H, P)
        return dst

    @staticmethod
    def modh(a, M, h, mod):
        r = a - ((M * (a & ((1 << 31) - 1)) >> 31) + M * (a >> 31) >> (h - 31)) * mod
        return r if r < mod else r - mod

    @staticmethod
    def pow(a, n, mod):
        ret = 1
        x = n.bit_length() - 1
        for x in range(x, -1, -1):
            ret = ret * ret % mod
            if (n >> x) & 1:
                ret = ret * a % mod
        return ret

    @staticmethod
    def invl(a, mod):
        b = mod
        p, q = 1, 0
        while b > 0:
            c = a // b
            d = a
            a = b
            b = d % b
            d = p
            p = q
            q = d - c * q
        return p + mod if p < 0 else p

def main():
    in_stream = InputReader(sys.stdin)
    out_stream = sys.stdout
    solver = LuckyTickets()
    solver.solve(1, in_stream, out_stream)

if __name__ == "__main__":
    main()

